import 'package:antigua_business_map/core/theme/app_colors.dart';
import 'package:flutter/material.dart';

/// The Dadliplug mark: a yellow map pin with a navy palm (2026-10-28
/// redesign).
///
/// `assets/images/logo_pin.png` is generated by `scripts/make_pin_logo.py`
/// from the palm logo in docs/design/brand, so the mark, the launcher icon
/// and the source logo cannot drift apart.
class DadliplugMark extends StatelessWidget {
  const DadliplugMark({this.size = 40, super.key});

  final double size;

  @override
  Widget build(BuildContext context) {
    return Image.asset(
      'assets/images/logo_pin.png',
      width: size,
      height: size,
      semanticLabel: 'Dadliplug',
    );
  }
}

/// Brand colours from the redesign.
abstract final class DadliplugColors {
  static const Color navy = Color(0xFF0A1F44);
  static const Color yellow = Color(0xFFFFC72C);
}

/// The pin with the wordmark: "Dadli" in white (navy on light), "plug" in
/// yellow, and ANTIGUA & BARBUDA underneath, as in the Home header.
class DadliplugLogo extends StatelessWidget {
  const DadliplugLogo({
    this.showTagline = true,
    this.onDark,
    this.scale = 1,
    super.key,
  });

  final bool showTagline;

  /// Forces the white wordmark, for logos on photos or navy headers in light
  /// mode. Defaults to following the theme.
  final bool? onDark;

  final double scale;

  static const String tagline = 'Local Businesses. Real Opportunities.';

  @override
  Widget build(BuildContext context) {
    final palette = context.palette;
    final light = onDark ?? palette.isDark;
    final ink = light ? Colors.white : DadliplugColors.navy;
    // On a light background the yellow "plug" needs an edge to be read.
    final plug = light ? DadliplugColors.yellow : const Color(0xFFE0A800);

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        DadliplugMark(size: 46 * scale),
        SizedBox(width: 6 * scale),
        Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text.rich(
              TextSpan(
                children: [
                  TextSpan(
                    text: 'Dadli',
                    style: TextStyle(color: ink),
                  ),
                  TextSpan(
                    text: 'plug',
                    style: TextStyle(color: plug),
                  ),
                ],
              ),
              style: TextStyle(
                fontSize: 28 * scale,
                fontWeight: FontWeight.w900,
                height: 1.0,
                letterSpacing: -0.5,
              ),
            ),
            if (showTagline)
              Text(
                'ANTIGUA & BARBUDA',
                style: TextStyle(
                  fontSize: 9.5 * scale,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 2.2 * scale,
                  color: ink.withValues(alpha: 0.85),
                ),
              ),
          ],
        ),
      ],
    );
  }
}
